const env = global.get('env') || {};
if (env.ENERGY_SOURCE_MODE !== 'device' && env.ENERGY_SOURCE_MODE !== 'modbus') {
  node.status({ fill: 'grey', shape: 'dot', text: 'Modbus mode idle (' + env.ENERGY_SOURCE_MODE + ')' });
  return null;
}

const map = global.get('modbusMap') || { READ: [] };
const activeRegisters = map.READ.filter(r => r && r.address !== null && r.address !== undefined);

if (activeRegisters.length === 0) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'Register belum di-set (address: null)' });
  return null;
}

node.status({ fill: 'blue', shape: 'dot', text: 'Polling ' + activeRegisters.length + ' registers...' });

// Generate read requests for flex-getter
const msgs = activeRegisters.map(reg => {
  let qty = 1;
  if (reg.type === 'float32' || reg.type === 'int32' || reg.type === 'uint32') {
    qty = 2;
  }
  return {
    payload: {
      value: '',
      unitid: reg.unitId,
      fc: reg.fc || 3,
      address: reg.address,
      quantity: qty
    },
    meta: reg
  };
});

return [msgs];

const meta = msg.meta;
if (!meta) return null;

const values = msg.payload;
if (!values || !Array.isArray(values)) return null;

let rawVal = 0;
const scale = meta.scale || 1.0;

if (meta.type === 'float32') {
  let w1 = values[0] || 0;
  let w2 = values[1] || 0;
  if (meta.wordSwap) {
    const temp = w1; w1 = w2; w2 = temp;
  }
  const buf = Buffer.alloc(4);
  buf.writeUInt16BE(w1, 0);
  buf.writeUInt16BE(w2, 2);
  rawVal = buf.readFloatBE(0);
} else if (meta.type === 'uint32') {
  let w1 = values[0] || 0;
  let w2 = values[1] || 0;
  if (meta.wordSwap) {
    const temp = w1; w1 = w2; w2 = temp;
  }
  rawVal = (w1 << 16) | w2;
} else if (meta.type === 'int32') {
  let w1 = values[0] || 0;
  let w2 = values[1] || 0;
  if (meta.wordSwap) {
    const temp = w1; w1 = w2; w2 = temp;
  }
  const buf = Buffer.alloc(4);
  buf.writeUInt16BE(w1, 0);
  buf.writeUInt16BE(w2, 2);
  rawVal = buf.readInt32BE(0);
} else if (meta.type === 'int16') {
  const buf = Buffer.alloc(2);
  buf.writeUInt16BE(values[0] || 0, 0);
  rawVal = buf.readInt16BE(0);
} else {
  rawVal = values[0] || 0;
}

const finalVal = Math.round(rawVal * scale * 10) / 10;

// Store reading in context buffer for aggregation
let buffer = context.get('buffer') || {
  'kwh-besar': { values: {}, count: 0, lastTs: 0 },
  'kwh-kecil': { values: {}, count: 0, lastTs: 0 }
};

const meter = meta.meter || 'kwh-besar';
if (!buffer[meter]) {
  buffer[meter] = { values: {}, count: 0, lastTs: 0 };
}

buffer[meter].values[meta.key] = finalVal;
buffer[meter].count++;
buffer[meter].lastTs = Date.now();

// Check map for required parameters for this meter
const map = global.get('modbusMap') || { READ: [] };
const meterRegs = map.READ.filter(r => r.meter === meter && r.address !== null);

// Emit batch when all active registers of this meter are collected
if (Object.keys(buffer[meter].values).length >= meterRegs.length && meterRegs.length > 0) {
  const payload = {
    readings: [{
      meterId: meter,
      timestamp: new Date().toISOString(),
      connectionStatus: 'online',
      source: 'device',
      values: Object.assign({}, buffer[meter].values)
    }]
  };

  // Reset meter values for next cycle
  buffer[meter].values = {};
  context.set('buffer', buffer);

  node.status({ fill: 'green', shape: 'dot', text: meter + ' read ok' });
  return { payload: payload };
}

context.set('buffer', buffer);
return null;

const err = msg.error || {};
node.status({ fill: 'red', shape: 'dot', text: 'Modbus error: ' + (err.message || 'unknown') });

const meter = (msg.meta && msg.meta.meter) || 'kwh-besar';
msg.payload = {
  readings: [{
    meterId: meter,
    timestamp: new Date().toISOString(),
    connectionStatus: 'error',
    source: 'device',
    values: null,
    error: err.message || 'Modbus communication timeout/error'
  }]
};
return msg;

const env = global.get('env') || {};
const reqSecret = (msg.req && msg.req.headers['x-internal-secret']) || '';

if (reqSecret !== (env.INTERNAL_API_SECRET || '')) {
  msg.statusCode = 401;
  msg.payload = { success: false, error: 'Unauthorized: invalid internal secret' };
  node.status({ fill: 'red', shape: 'ring', text: '401 Unauthorized' });
  return [null, msg];
}

const body = msg.payload || {};
const tag = body.tag;
const val = body.value;

if (!tag || val === undefined) {
  msg.statusCode = 400;
  msg.payload = { success: false, error: 'Missing tag or value in request' };
  return [null, msg];
}

const envMode = env.ENERGY_SOURCE_MODE || 'modbus';
if (envMode === 'simulation') {
  node.status({ fill: 'green', shape: 'dot', text: 'Sim write: ' + tag + ' = ' + val });
  msg.statusCode = 200;
  msg.payload = {
    success: true,
    message: 'Simulated write to ' + tag + ' (' + val + ') successful',
    tag: tag,
    value: val
  };
  return [null, msg];
}

const map = global.get('modbusMap') || { WRITE: [] };
const point = (map.WRITE || []).find(p => p.tag === tag);

if (!point) {
  msg.statusCode = 404;
  msg.payload = { success: false, error: 'Control point tag "' + tag + '" not found in Register Map' };
  return [null, msg];
}

let encodedValue = val;
let qty = 1;

if (point.type === 'bool') {
  encodedValue = Boolean(val);
} else if (point.type === 'float32') {
  qty = 2;
  const numVal = Number(val) / (point.scale || 1.0);
  const buf = Buffer.alloc(4);
  buf.writeFloatBE(numVal, 0);
  const w1 = buf.readUInt16BE(0);
  const w2 = buf.readUInt16BE(2);
  encodedValue = point.wordSwap ? [w2, w1] : [w1, w2];
} else {
  const numVal = Math.round(Number(val) / (point.scale || 1.0));
  encodedValue = numVal;
}

msg.pointTag = tag;
msg.pointValue = val;
msg.payload = {
  value: encodedValue,
  unitid: point.unitId || 1,
  fc: point.fc || 16,
  address: point.address,
  quantity: qty
};

node.status({ fill: 'blue', shape: 'dot', text: 'Writing ' + tag + ' = ' + val });
return [msg, null];

node.status({ fill: 'green', shape: 'dot', text: 'Write ok: ' + msg.pointTag });
msg.statusCode = 200;
msg.payload = {
  success: true,
  message: 'Modbus write operation executed successfully',
  tag: msg.pointTag,
  value: msg.pointValue
};
return msg;

node.status({ fill: 'red', shape: 'dot', text: 'Write failed: ' + msg.pointTag });
msg.statusCode = 502;
msg.payload = {
  success: false,
  error: 'Modbus write failed to execute on device'
};
return msg;

const map = global.get('modbusMap') || { WRITE: [] };
msg.statusCode = 200;
msg.payload = {
  points: map.WRITE || []
};
return msg;

const env = global.get('env') || {};
if (env.ENERGY_SOURCE_MODE !== 'simulation') {
  node.status({ fill: 'grey', shape: 'dot', text: 'Simulator idle (mode: ' + env.ENERGY_SOURCE_MODE + ')' });
  return null;
}

let state = context.get('state');
if (!state) {
  state = {
    lastTick: Date.now(),
    kwhBesar: {
      kwhR: 373.0,
      kwhS: 313.0,
      kwhT: 688.0
    },
    kwhKecil: {
      kwhR: 137.0,
      kwhS: 286.0,
      kwhT: 450.0
    }
  };
}

const now = Date.now();
const dtHours = Math.max(0.0001, (now - state.lastTick) / 3600000);
state.lastTick = now;

function jitter(base, amplitude) {
  const delta = (Math.random() * 2 - 1) * amplitude;
  return Math.round((base + delta) * 10) / 10;
}

// KWH BESAR (Meter 1)
const vbR = jitter(215.0, 1.2);
const vbS = jitter(222.1, 1.5);
const vbT = jitter(219.1, 1.3);

const ibR = jitter(3.0, 0.4);
const ibS = jitter(3.9, 0.5);
const ibT = jitter(25.5, 1.8);

const wbR = Math.round(vbR * ibR * 0.728 * 10) / 10;
const wbS = Math.round(vbS * ibS * 0.903 * 10) / 10;
const wbT = Math.round(vbT * ibT * 0.998 * 10) / 10;
const totalWattBesar = Math.round((wbR + wbS + wbT) * 10) / 10;

state.kwhBesar.kwhR += (wbR * dtHours) / 1000;
state.kwhBesar.kwhS += (wbS * dtHours) / 1000;
state.kwhBesar.kwhT += (wbT * dtHours) / 1000;
const totalKwhBesar = Math.round((state.kwhBesar.kwhR + state.kwhBesar.kwhS + state.kwhBesar.kwhT) * 10) / 10;

// KWH KECIL (Meter 2)
const vkR = jitter(214.6, 1.1);
const vkS = jitter(220.7, 1.4);
const vkT = jitter(220.7, 1.2);

const ikR = jitter(6.6, 0.6);
const ikS = jitter(14.1, 1.1);
const ikT = jitter(6.4, 0.5);

const wkR = Math.round(vkR * ikR * 1.002 * 10) / 10;
const wkS = Math.round(vkS * ikS * 1.002 * 10) / 10;
const wkT = Math.round(vkT * ikT * 0.966 * 10) / 10;
const totalWattKecil = Math.round((wkR + wkS + wkT) * 10) / 10;

state.kwhKecil.kwhR += (wkR * dtHours) / 1000;
state.kwhKecil.kwhS += (wkS * dtHours) / 1000;
state.kwhKecil.kwhT += (wkT * dtHours) / 1000;
const totalKwhKecil = Math.round((state.kwhKecil.kwhR + state.kwhKecil.kwhS + state.kwhKecil.kwhT) * 10) / 10;

context.set('state', state);

const isoTimestamp = new Date(now).toISOString();

msg.payload = {
  readings: [
    {
      meterId: 'kwh-besar',
      timestamp: isoTimestamp,
      connectionStatus: 'online',
      source: 'simulation',
      values: {
        voltageR: vbR,
        voltageS: vbS,
        voltageT: vbT,
        currentR: ibR,
        currentS: ibS,
        currentT: ibT,
        wattR: wbR,
        wattS: wbS,
        wattT: wbT,
        kwhR: Math.round(state.kwhBesar.kwhR * 10) / 10,
        kwhS: Math.round(state.kwhBesar.kwhS * 10) / 10,
        kwhT: Math.round(state.kwhBesar.kwhT * 10) / 10,
        totalWatt: totalWattBesar,
        totalKwh: totalKwhBesar
      }
    },
    {
      meterId: 'kwh-kecil',
      timestamp: isoTimestamp,
      connectionStatus: 'online',
      source: 'simulation',
      values: {
        voltageR: vkR,
        voltageS: vkS,
        voltageT: vkT,
        currentR: ikR,
        currentS: ikS,
        currentT: ikT,
        wattR: wkR,
        wattS: wkS,
        wattT: wkT,
        kwhR: Math.round(state.kwhKecil.kwhR * 10) / 10,
        kwhS: Math.round(state.kwhKecil.kwhS * 10) / 10,
        kwhT: Math.round(state.kwhKecil.kwhT * 10) / 10,
        totalWatt: totalWattKecil,
        totalKwh: totalKwhKecil
      }
    }
  ]
};

node.status({ fill: 'green', shape: 'dot', text: 'Simulating [28 params] - ' + isoTimestamp.substring(11, 19) });
return msg;

const env = global.get('env') || {};
msg.url = (env.BACKEND_URL || 'http://backend:3000') + '/api/internal/telemetry';
msg.headers = {
  'Content-Type': 'application/json',
  'X-Internal-Secret': env.INTERNAL_API_SECRET || ''
};
return msg;

const code = msg.statusCode;
if (code === 202 || code === 200) {
  node.status({ fill: 'green', shape: 'dot', text: 'Sent (' + code + ') ' + new Date().toISOString().substring(11, 19) });
} else {
  node.status({ fill: 'red', shape: 'dot', text: 'Failed (HTTP ' + code + ')' });
}
return msg;
